# ----------------------------------------------------------------------------- helpers
def words(text) -> int:
    return len(str(text or "").split())


def read_text(path) -> str:
    """A text file as UTF-8 with \\n line ends, whatever the machine's locale says. A byte-order mark is
    tolerated (Windows PowerShell's `>` writes UTF-16, some editors put a mark before UTF-8) and a
    stray byte is replaced, so a file made on another machine loads instead of ending the run."""
    data = Path(path).read_bytes()
    if data[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return data.decode("utf-16", errors="replace").replace("\r\n", "\n")
    return data.decode("utf-8-sig", errors="replace").replace("\r\n", "\n")


def utf8_console() -> None:
    """Print UTF-8 with \\n line ends whatever the system. On Windows a pipe defaults to a legacy code
    page that has no arrow, so `7→5→3→1` would end the command with an encoding error, and to \\r\\n,
    so the same command would print other bytes there than everywhere else. Never fatal."""
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding="utf-8", errors="replace", newline="\n")
        except (AttributeError, ValueError, OSError):
            pass
    if not isinstance(sys.stdout, _Console):                    # file names and seat text can carry escape sequences
        sys.stdout, sys.stderr = _Console(sys.stdout), _Console(sys.stderr)


def now():
    """The local time now, or the frozen time in COUNCIL_NOW (2026-11-13T12:00:00). Tests and the parity
    suite freeze the clock so that two runs of the same steps write the same ids, dates and ledgers."""
    import datetime as dt
    frozen = os.environ.get("COUNCIL_NOW")
    if frozen:
        try:
            return dt.datetime.strptime(frozen.strip(), "%Y-%m-%dT%H:%M:%S")
        except ValueError:
            pass
    return dt.datetime.now()


def today():
    return now().date()


def load_yaml(path: Path):
    import yaml  # PyYAML
    return yaml.safe_load(read_text(path))


# ----------------------------------------------------------------------------- safety: where this tool writes, what it reads and prints
class Refused(Exception):
    """The tool will not do this, and says why. The command line prints `error: ...` and exits with 2."""


MAX_DEPTH = 127                                   # nesting the Rust build's JSON parser allows; both refuse deeper input
MAX_OUTPUT = 2_000_000                            # bytes of one seat output; a larger file is refused unread
MAX_LOCKED = 64_000_000                           # bytes of one locked file
_EXTRA_ROOTS: list[Path] = []                     # a project given by its path, and memory folders your own settings name
_CONTROL = {c: "\ufffd" for c in (*range(0, 9), 11, 12, *range(14, 32), 127, *range(128, 160),
                                  *range(0x202A, 0x202F), *range(0x2066, 0x206A))}
_CONTROL[13] = None                               # a carriage return could overwrite the line it is printed on
_JSON_TOKEN = re.compile(r'"(?:\\.|[^"\\])*"|[\[\]{}]')


def shown(text: str) -> str:
    """Text that is safe to print or to put in a packet: control characters (the escape sequences that
    drive a terminal among them) and Unicode's direction overrides become U+FFFD. Tabs and line ends stay."""
    return text.translate(_CONTROL)


def unfence(raw: str) -> str:
    """A document without the code fence a model sometimes puts around the whole of it."""
    text = raw.strip()
    first, _, rest = text.partition("\n")
    if first.strip() in ("```", "```markdown", "```md") and rest.rstrip().endswith("```"):
        body = rest.rstrip()[:-3]
        if body.endswith("\n"):
            return body[:-1].strip()
    return text


def cleaned(value):
    """A parsed JSON or YAML value with every string passed through shown(): what a seat or a file
    said, without the characters that could steer a terminal or hide text from a reader."""
    if isinstance(value, str):
        return shown(value)
    if isinstance(value, list):
        return [cleaned(v) for v in value]
    if isinstance(value, dict):
        return {(shown(k) if isinstance(k, str) else k): cleaned(v) for k, v in value.items()}
    return value


def load_json(text: str):
    """json.loads with the one nesting limit both implementations share. Without it a file nested a
    thousand levels deep ends Python with a RecursionError where the Rust build says "not valid JSON"."""
    depth = deepest = 0
    for m in _JSON_TOKEN.finditer(text):
        tok = m.group(0)
        if tok in "[{":
            depth += 1
            deepest = max(deepest, depth)
        elif tok in "]}":
            depth -= 1
    if deepest > MAX_DEPTH:
        raise ValueError(f"nested {deepest} levels deep (the limit is {MAX_DEPTH})")
    return json.loads(text)


def allow_root(path) -> None:
    """Name a folder this tool may write under: a project given by its path, or a memory folder that
    your own settings or the environment name. Never called with a value read from a project."""
    p = Path(path)
    if p not in _EXTRA_ROOTS:
        _EXTRA_ROOTS.append(p)


def private_dir() -> Path:
    return Path(os.environ.get("COUNCIL_PRIVATE_DIR") or Path.home() / ".council-private")


def _real(path) -> Path:
    """The path with every symbolic link followed, whether or not all of it exists yet."""
    return Path(os.path.realpath(path))


def within(path, root) -> bool:
    """Is path, with links followed, inside root (or root itself)?"""
    a, b = _real(path), _real(root)
    return a == b or b in a.parents


def guard(path, folder: bool = False) -> Path:
    """Refuse a path this tool must not write: a symbolic link, or a place that, with links followed,
    lies outside the project, your settings folder, the private folder and the memory your own
    settings name. A repository can hold links that point anywhere; following one would let its author
    choose where this tool writes."""
    p = Path(path)
    p = p if p.is_absolute() else Path.cwd() / p
    if p.is_symlink():
        raise Refused(f"refusing to write {p}: it is a symbolic link")
    place = p if folder else p.parent
    try:
        roots = [project_root(), user_config_path().parent, private_dir(), *_EXTRA_ROOTS]
    except OSError:
        roots = list(_EXTRA_ROOTS)
    if not any(within(place, r) for r in roots):
        raise Refused(f"refusing to write {p}: with links followed it lies outside the project")
    return p


def write_text(path, text: str, named: bool = False) -> None:
    """The one way this tool writes a file: UTF-8, \\n line ends on every system, and only where it
    should (see guard). named=True: the person named this path on the command line; it is theirs to choose."""
    p = Path(path) if named else guard(path)
    p.write_text(text, encoding="utf-8", newline="\n")


def make_dir(path, new: bool = False) -> Path:
    """Create a folder (and its parents) where this tool may write. new=True: it must not exist yet."""
    p = guard(path, folder=True)
    p.mkdir(parents=True, exist_ok=not new)
    return p


def private_file(path, text: str) -> None:
    """Write a file only its owner may read (who wrote which card must stay away from the seats and
    from other accounts on the machine). On Windows the folder's own permissions apply."""
    p = guard(path)
    p.write_text(text, encoding="utf-8", newline="\n")
    try:
        os.chmod(p, 0o600)
        os.chmod(p.parent, 0o700)
    except OSError:
        pass


def git(root, *args) -> list[str]:
    """A git command line for a repository this tool did not create. The repository's own settings
    can name programs for git to run (core.fsmonitor, for one); those are switched off, and git is
    told not to take locks, so that looking at a repository never runs or changes anything in it."""
    return ["git", "-c", "core.fsmonitor=false", "-c", "core.hooksPath=", "--no-optional-locks", "-C", str(root), *args]


def simple_pattern(rx) -> str | None:
    """None when rx is a pattern this tool will run from a settings file, else why not. Settings files
    come with a repository, and a pattern can be written to make a matcher run for hours. So only
    plain ones are taken: words, classes, groups, `|`, at most two open-ended repeats, and nothing
    but `?` after a group. Both implementations take exactly the same patterns."""
    if not isinstance(rx, str):
        return "it is not text"
    if len(rx) > 200:
        return "it is longer than 200 characters"
    i, n, open_ended, prev, depth = 0, len(rx), 0, None, 0     # prev: "atom", "group" or None (nothing to repeat)
    while i < n:
        c = rx[i]
        if c == "\\":
            e = rx[i + 1] if i + 1 < n else ""
            if not e:
                return "it ends in a backslash"
            if not (e in "bBdDwWsStnr" or (e.isascii() and not e.isalnum() and not e.isspace())):
                return f"\\{e} is not allowed"
            i, prev = i + 2, (None if e in "bB" else "atom")
        elif c == "[":
            j = i + 1
            if j < n and rx[j] == "^":
                j += 1
            if j < n and rx[j] == "]":
                j += 1
            while j < n and rx[j] != "]":
                if rx[j] == "[" or rx[j:j + 2] in ("&&", "--", "~~"):
                    return "a class may not hold [, &&, -- or ~~"
                j += 2 if rx[j] == "\\" else 1
            if j >= n:
                return "a [ is not closed"
            i, prev = j + 1, "atom"
        elif c == "(":
            if rx.startswith("(?", i) and not rx.startswith("(?:", i):
                return "only plain groups and (?:...) are allowed"
            depth, i, prev = depth + 1, i + (3 if rx.startswith("(?:", i) else 1), None
        elif c == ")":
            if depth == 0:
                return "a ) has no ("
            depth, i, prev = depth - 1, i + 1, "group"
        elif c in "*+?{":
            if prev is None:
                return "a repeat has nothing to repeat"
            kind = "open" if c in "*+" else "closed"
            if c == "{":
                m = re.match(r"\{(\d{1,3})(,(\d{0,3}))?\}", rx[i:i + 10])
                if not m:
                    return "a { must be a repeat count such as {2,5}"
                if m.group(2) and not m.group(3):
                    kind = "open"
                elif int(m.group(3) or m.group(1)) > 50 or int(m.group(1)) > int(m.group(3) or m.group(1)):
                    return "a repeat count must run from low to high and stay under 51"
                i += m.end() - 1
            if prev == "group" and c != "?":
                return "only ? may follow a group"
            open_ended += kind == "open"
            i += 1
            if i < n and rx[i] == "?":
                i += 1                                          # the lazy form
            elif i < n and rx[i] == "+":
                return "a + after a repeat is not allowed"
            prev = None
        elif c in "|^$":
            i, prev = i + 1, None
        elif c in "}]":
            return f"a {c} has nothing to close"
        else:
            i, prev = i + 1, "atom"
    if depth:
        return "a ( is not closed"
    if open_ended > 2:
        return "more than two open-ended repeats (*, + or {n,})"
    try:
        re.compile(rx)
    except re.error:
        return "it is not a valid pattern"
    return None


class _Console:
    """What the command line prints through: the same stream, with shown() applied to every write."""

    def __init__(self, stream):
        self._stream = stream

    def write(self, text):
        return self._stream.write(shown(text) if isinstance(text, str) else text)

    def __getattr__(self, name):
        return getattr(self._stream, name)


def labels_for(n: int) -> list[str]:
    out, i = [], 0
    while len(out) < n:
        q, r = divmod(i, 26)
        out.append((chr(65 + q - 1) if q else "") + chr(65 + r))
        i += 1
    return out


def project_root(start: Path | None = None) -> Path:
    """Nearest ancestor holding .council/ or .git; else the current directory. Your own settings folder
    (~/.council) does not count: it must not turn the home directory into the project for every
    folder beneath it that has no .git yet."""
    p = (start or Path.cwd()).resolve()
    try:
        own = user_config_path().parent.resolve()
    except OSError:
        own = None
    for cand in (p, *p.parents):
        if (cand / ".git").exists() or ((cand / ".council").is_dir() and (cand / ".council").resolve() != own):
            return cand
    return p


def config(root: Path | None = None) -> dict:
    path = (root or project_root()) / ".council" / "config.yaml"
    try:
        data = load_yaml(path) if path.exists() else None
    except Exception:  # noqa: BLE001 - a broken optional config must not break the gate
        return {}
    return data if isinstance(data, dict) else {}       # a file whose top level is a list is not a config


def authors_of(card: dict) -> list[str]:
    a = card.get("authors", card.get("author"))
    if a is None:
        return []
    return [a] if isinstance(a, str) else list(a)


# ----------------------------------------------------------------------------- doctor
def doctor(root: Path | None = None, probe: bool = False) -> dict:
    """What can be called from here? Recommends a mode. Spends no tokens unless probe=True, which
    sends one tiny test prompt to each installed CLI (an installed CLI may still be logged out)."""
    notes_probe: list[str] = []
    cli = {name: bool(shutil.which(name)) for name in ("claude", "codex", "gemini")}
    claude_code = os.environ.get("CLAUDECODE") == "1"
    openrouter = bool(os.environ.get("OPENROUTER_API_KEY"))
    labs = {"Anthropic": claude_code or cli["claude"], "OpenAI": cli["codex"] or openrouter,
            "Google": cli["gemini"] or openrouter}
    lock_path = SKILL_DIR / "models" / "lock.yaml"
    lock = {"exists": lock_path.exists(), "age_days": None, "stale": None}
    if lock_path.exists():
        import datetime as dt
        try:
            data = load_yaml(lock_path)
            limit = (load_yaml(SKILL_DIR / "models" / "policy.yaml") or {}).get("data", {}).get("stale_after_days", 30)
            age = (today() - dt.date.fromisoformat(str(data["data"]["collected"]))).days
            lock.update(age_days=age, stale=age > limit, collected=str(data["data"]["collected"]))
        except Exception as err:  # noqa: BLE001
            lock["error"] = str(err)
    reachable = [lab for lab, ok in labs.items() if ok]
    if len(reachable) >= 2:
        mode = "crosslab"
    elif labs["Anthropic"]:
        mode = "fanout:claude"
    elif labs["OpenAI"]:
        mode = "fanout:openai"
    elif labs["Google"]:
        mode = "fanout:gemini"
    else:
        mode = "solo"
    notes = []
    missing = [lab for lab, ok in labs.items() if not ok]
    if mode == "crosslab" and missing:
        notes.append(f"{', '.join(missing)} not reachable: those seats become labelled stand-ins")
    if mode.startswith("fanout:") or mode == "solo":
        notes.append("only one lab reachable: elders come from the same family (no cross-lab check). "
                     "Install the codex / gemini CLIs or set OPENROUTER_API_KEY to get one")
    if lock.get("stale"):
        notes.append(f"model data is {lock['age_days']} days old: run `council refresh`")
    if not lock["exists"]:
        notes.append("models/lock.yaml missing: run `council refresh --offline <snapshot>`")
    fresh = "subagents" if claude_code else next((f"cli:{c}" for c in ("claude", "codex", "gemini") if cli[c]), "none")
    forced = os.environ.get("COUNCIL_SEATS_VIA")               # subagents | cli:claude | cli:codex | cli:gemini | none
    if forced:
        fresh = forced
    probes = {}
    if probe:
        import providers
        for name, prov in (("claude", "claude"), ("codex", "openai"), ("gemini", "gemini")):
            if cli[name]:
                res = providers.ask(prov, "Reply with exactly the two letters: OK", timeout=90)
                ok = bool(res.get("ok")) and "OK" in str(res.get("text", "")).upper() and "ERROR" not in str(res.get("text", "")).upper()
                probes[name] = "ok" if ok else f"FAILED: {' '.join(str(res.get('text') or res.get('error') or '').split())[:120]}"
                if not ok:
                    notes_probe.append(f"the {name} CLI is installed but did not answer a test prompt: {probes[name]}")
    if fresh == "none":
        notes.append("no way to start fresh contexts: seats will run in the chair's context (logged as a deviation)")
    notes += notes_probe
    import memory as shared_memory
    mem = shared_memory.settings(root)
    if not mem["ok"]:
        notes.append(mem["problem"])
    return {"claude_code": claude_code, "cli": cli, **({"probes": probes} if probe else {}), "openrouter_key": openrouter,
            "aa_key": bool(os.environ.get("AA_API_KEY")), "labs_reachable": labs, "fresh_contexts": fresh,
            "lock": lock, "recommended_mode": mode, "notes": notes, "python": sys.version.split()[0],
            "memory": {k: mem.get(k) for k in ("backend", "dir", "source", "ok")}}


# ----------------------------------------------------------------------------- gate / plan
def tripwire_rules(root: Path | None = None) -> tuple[dict, dict, list[str]]:
    """The built-in tripwires plus the project's own, and what was wrong with the project's.
    A pattern from a settings file must be a plain one (see simple_pattern): the file comes with the
    repository, and its author is not always a friend."""
    cfg = config(root)
    text_rules, path_rules, problems = dict(TRIPWIRES), dict(TRIPWIRE_PATHS), []
    own = cfg.get("tripwires")
    if isinstance(own, dict):
        for name, rx in own.items():
            why = simple_pattern(rx)
            if why:
                problems.append(f"tripwire {str(name)!r} in .council/config.yaml was ignored: {why}")
            else:
                text_rules[str(name)] = rx
    elif own is not None:
        problems.append("tripwires in .council/config.yaml must map a name to a pattern: ignored")
    own = cfg.get("tripwire_paths")
    if isinstance(own, dict):
        for name, globs in own.items():
            globs = [globs] if isinstance(globs, str) else globs
            if isinstance(globs, list) and globs and all(isinstance(g, str) for g in globs):
                path_rules[str(name)] = globs
            else:
                problems.append(f"tripwire_paths {str(name)!r} in .council/config.yaml was ignored: it must be a list of globs")
    elif own is not None:
        problems.append("tripwire_paths in .council/config.yaml must map a name to a list of globs: ignored")
    return text_rules, path_rules, problems


def tripwires_hit(task: str, paths: list[str] | None = None, root: Path | None = None) -> list[str]:
    text_rules, path_rules, _ = tripwire_rules(root)
    hits = [name for name, rx in text_rules.items() if re.search(rx, task or "", re.I)]
    for name, globs in path_rules.items():
        if any(fnmatch.fnmatch(p, g) for p in (paths or []) for g in globs) and name not in hits:
            hits.append(name)
    return hits


def schedule_for(start: int, loops: int) -> list[int]:
    """Candidates at the start, then survivors after each loop: cut 2 per loop, end at 1."""
    out, cur = [start], start
    for i in range(loops):
        remaining = loops - i - 1
        cur = 1 if remaining == 0 else max(remaining + 1, cur - 2)
        out.append(cur)
    return out


