            return shared_memory.cmd_import(a.src)
        except shared_memory.MemoryError_ as err:
            print(f"error: {err}", file=sys.stderr)
            return 2
    if a.cmd in ("init", "next", "status", "dispatch", "ingest", "cut", "deviation", "audit", "note"):
